// Word Guess: find the hidden word of five letters (the owner's "Wordle", named generically). Pick
// a topic (Places, Animals, Food, Nature, Home, Sports), a mix, or today's word (the same on every
// device that day). Type a word: each letter turns green (right letter, right square), yellow (in
// the word, another square) or grey (not in the word, or not again). Guess until you find it; the
// fewer guesses the better. Hint shows one right letter in its square, or, once every square is
// known, puts in the word.
//
// The guesses it takes: every topic's words, and SCOWL's five-letter words up to size 50
// (http://wordlist.aspell.net) with ENABLE's (public domain), made by tools/word-list.mjs. SCOWL:
// Copyright 2000-2018 by Kevin Atkinson. Permission to use, copy, modify, distribute and sell these
// word lists, the associated scripts, the output created from the scripts, and its documentation
// for any purpose is hereby granted without fee, provided that the above copyright notice appears
// in all copies and that both that copyright notice and this permission notice appear in
// supporting documentation. Kevin Atkinson makes no representations about the suitability of this
// array for any purpose. It is provided "as is" without express or implied warranty.
import { copy } from "../../lib/board.js";
import { int } from "../../lib/rng.js";

export const LENGTH = 5;
// Every match ends: after this many moves the word is filled in.
const MAX_MOVES = 60;

/** The words of each topic: common, clear and five letters long. Places has cities and countries. */
export const TOPICS = {
  places:
    "paris tokyo delhi cairo dubai miami osaka milan seoul dhaka china japan india egypt italy spain kenya nepal chile ghana wales qatar malta beach coast river ocean field hotel plaza cabin tower villa ridge cliff swamp marsh grove oasis delta canal manor abbey arena court diner track stage store hills lakes shore bayou creek farms",
  animals:
    "tiger zebra horse sheep mouse camel snake eagle whale shark otter panda koala llama moose goose robin raven hippo rhino bison hyena lemur sloth skunk gecko squid trout puppy bunny chick finch stork crane heron viper cobra dingo tapir quail hound",
  food: "apple grape lemon mango peach melon berry guava olive onion bread pizza pasta salad sushi curry toast bagel donut candy cream honey juice sauce steak bacon chips fries wafer crepe gravy jelly wheat flour sugar spice chili lassi dates seeds",
  nature:
    "cloud storm sunny earth plant grass bloom petal stone rocks shore frost snowy flake light night stars comet orbit trees maple cedar birch daisy tulip lotus roses brook flood windy rainy misty water thorn",
  home: "chair table couch shelf clock spoon plate glass knife towel sheet quilt bench stool stove broom brush paint floor porch attic house piano radio phone fence lamps sofas linen duvet patio chest",
  sports:
    "chess darts rugby dance skate kayak racer match score goals pitch court medal coach serve catch throw swing relay track climb cycle skier boxer bowls rider squat lifts point diver stump spike block",
};
const ANSWERS = Object.fromEntries(Object.entries(TOPICS).map(([k, v]) => [k, v.split(" ")]));
// Today's word and a mix: every topic's words, each once, in a fixed order.
const ALL = [...new Set(Object.values(ANSWERS).flat())].sort();

let valid = null;
/** Is it a word the game takes as a guess (lower case)? */
export function isGuess(word) {
  if (!valid) {
    valid = new Set(ALL);
    for (let i = 0; i < GUESSES.length; i += LENGTH) valid.add(GUESSES.slice(i, i + LENGTH));
  }
  return valid.has(word);
}

/**
 * The marks for a guess: "g" right square, "y" in the word elsewhere, "-" not (or not again). Greens
 * first, then yellows from what is left, so a letter is never marked more times than it is there.
 */
export function marks(guess, answer) {
  const out = Array(LENGTH).fill("-");
  const left = {};
  for (let i = 0; i < LENGTH; i++) {
    if (guess[i] === answer[i]) out[i] = "g";
    else left[answer[i]] = (left[answer[i]] ?? 0) + 1;
  }
  for (let i = 0; i < LENGTH; i++) {
    if (out[i] === "g" || !left[guess[i]]) continue;
    out[i] = "y";
    left[guess[i]]--;
  }
  return out.join("");
}

function init(_seats, seed, pick) {
  const topic = Object.hasOwn(ANSWERS, pick) || pick === "mix" ? pick : "today";
  const holder = { rng: seed >>> 0 };
  const words = ANSWERS[topic] ?? ALL;
  return {
    rng: holder.rng,
    turn: 0,
    moves: 0,
    pick: topic,
    word: words[int(holder, words.length)],
    guesses: [],
    marks: [],
    shown: [],
    note: null,
  };
}

const solved = (s) => s.guesses.at(-1) === s.word;
/** The squares whose letter is known: green in a guess, or shown by a hint. */
const known = (s) => new Set([...s.shown, ...s.marks.flatMap((m) => [...m].flatMap((x, i) => (x === "g" ? [i] : [])))]);

// The hint: one right letter in its square, or the word itself once every square is known.
function hint(s) {
  const k = known(s);
  for (let i = 0; i < LENGTH; i++) if (!k.has(i)) return { t: "show", i };
  return { t: "guess", word: s.word };
}

// Any word of the list is a guess, so the list of moves holds only the hint; apply takes any guess.
function legalMoves(s, seat) {
  return seat !== 0 || solved(s) ? [] : [hint(s)];
}

function apply(s, seat, move) {
  if (seat !== 0) throw new Error("Only the solver plays this puzzle.");
  if (solved(s)) throw new Error("You found the word.");
  const next = copy(s);
  next.moves += 1;
  if (move?.t === "show") {
    if (!Number.isInteger(move.i) || move.i < 0 || move.i >= LENGTH || known(s).has(move.i))
      throw new Error("That letter is known already.");
    next.shown.push(move.i);
    next.note = `@0 took a hint: letter ${move.i + 1} is ${s.word[move.i].toUpperCase()}`;
  } else if (move?.t === "guess") {
    const word = typeof move.word === "string" ? move.word.toLowerCase() : "";
    if (!/^[a-z]{5}$/.test(word)) throw new Error("Type a word of five letters.");
    if (!isGuess(word)) throw new Error(`${word.toUpperCase()} isn't in the word list.`);
    if (s.guesses.includes(word)) throw new Error(`You tried ${word.toUpperCase()} already.`);
    next.guesses.push(word);
    next.marks.push(marks(word, s.word));
    const n = next.guesses.length;
    next.note = solved(next)
      ? `@0 found ${word.toUpperCase()} in ${n} ${n === 1 ? "guess" : "guesses"}`
      : `@0 tried ${word.toUpperCase()}`;
  } else throw new Error("Type a word of five letters.");
  // A match that runs this long ends with the word put in.
  if (!solved(next) && next.moves >= MAX_MOVES) {
    next.guesses.push(s.word);
    next.marks.push("g".repeat(LENGTH));
    next.note = `The word was ${s.word.toUpperCase()}`;
  }
  return next;
}

const winner = (s) => (solved(s) ? { places: [[0]] } : null);

// The word stays out of the view: only its letters shown by a hint are there.
function view(s) {
  return {
    pick: s.pick,
    guesses: s.guesses,
    marks: s.marks,
    shown: s.shown.map((i) => [i, s.word[i]]),
    done: solved(s),
  };
}

// Every level gives the hint (a puzzle has no CPU player).
const ai = (s) => hint(s);

export default {
  id: "word-guess",
  name: "Word Guess",
  version: 1,
  players: { min: 1, max: 1 },
  hidden: false,
  realtime: false,
  puzzle: true,
  init,
  view,
  legalMoves,
  apply,
  winner,
  ai,
};

const GUESSES = "";
